-- FROZEN v1 baseline of a tenant site.db. Copied verbatim from schema/site.sql at commit cc1a5b4
-- (PRAGMA user_version = 1) and never regenerated: it is the input to the migration chain
-- tests (scripts/model/verify_claims.py checks 9, 20). schema/site.sql is now the v3 target.
-- Editing this file invalidates the convergence proof.

-- site.db — generated by scripts/model/gen_schema.py
-- application_id 0x534B5701 lets install.sh refuse to open the wrong file.
PRAGMA application_id = 0x534B5701;
PRAGMA user_version = 1;
PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;

-- The only EAV-shaped table. Keys are registry-declared; unknown keys are rejected by the app.
CREATE TABLE cms_settings (
  key TEXT PRIMARY KEY CHECK(key GLOB '[a-z0-9._]*'),
  value_json TEXT NOT NULL,
  type TEXT NOT NULL CHECK(type IN ('int','bool','string','json','asset_key')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_by INTEGER
);

-- One document per page: the GrapesJS model is the source of truth, not a block tree.
CREATE TABLE cms_page (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  path TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(path GLOB '/*' AND path NOT GLOB '*..*' AND path NOT GLOB '*/'),
  slug TEXT NOT NULL CHECK(slug GLOB '[a-z0-9]*' AND slug NOT GLOB '*[^a-z0-9-]*'),
  title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 200),
  status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','hidden')),
  template TEXT NOT NULL DEFAULT 'page' CHECK(template IN ('page','landing','post','index')),
  body_html TEXT NOT NULL DEFAULT '',
  css TEXT NOT NULL DEFAULT '',
  seo_json TEXT,
  etag TEXT NOT NULL,
  published_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_by INTEGER
);
CREATE INDEX ix_page_status ON cms_page(status, published_at);

-- Append-only. Covers the designer who hand-edits HTML and breaks it.
CREATE TABLE cms_page_revision (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  page_id INTEGER NOT NULL REFERENCES cms_page(id) ON DELETE CASCADE,
  body_html TEXT NOT NULL,
  css TEXT NOT NULL,
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by INTEGER
);
CREATE INDEX ix_rev_page_ts ON cms_page_revision(page_id, created_at);

-- Adjacency list. Position uniqueness uses ifnull() because SQLite treats NULLs as distinct in UNIQUE.
CREATE TABLE cms_nav (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  location TEXT NOT NULL CHECK(location IN ('header','footer','sidebar')),
  parent_id INTEGER REFERENCES cms_nav(id) ON DELETE CASCADE,
  label TEXT NOT NULL CHECK(length(label) BETWEEN 1 AND 80),
  href_kind TEXT NOT NULL DEFAULT 'page' CHECK(href_kind IN ('page','asset','url')),
  href_target TEXT NOT NULL,
  position INTEGER NOT NULL DEFAULT 0 CHECK(position >= 0),
  visible INTEGER NOT NULL DEFAULT 1 CHECK(visible IN (0,1))
);
CREATE UNIQUE INDEX ux_nav_pos ON cms_nav(location, ifnull(parent_id,0), position);

-- Identity is key. sha256 is the physical address and is never referenced by content.
CREATE TABLE cms_asset (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(key = lower(key) AND length(key) BETWEEN 1 AND 96 AND key NOT GLOB '*[^a-z0-9/_.-]*' AND key NOT GLOB '/?*' AND key NOT GLOB '*/' AND key NOT GLOB '*..*' AND key NOT GLOB '.?*'),
  filename TEXT NOT NULL,
  mime TEXT NOT NULL,
  bytes INTEGER NOT NULL CHECK(bytes > 0),
  sha256 TEXT NOT NULL CHECK(length(sha256) = 64),
  kind TEXT NOT NULL CHECK(kind IN ('image','video','audio','document','archive')),
  access_class TEXT NOT NULL DEFAULT 'public' CHECK(access_class IN ('public','linked-private','gated')),
  storage_path TEXT NOT NULL,
  width INTEGER,
  height INTEGER,
  alt_text TEXT,
  caption TEXT,
  watermark_asset_id INTEGER REFERENCES cms_asset(id) ON DELETE SET NULL,
  watermark_spec_json TEXT,
  frozen_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by INTEGER,
  CHECK(kind <> 'image' OR (width IS NOT NULL AND height IS NOT NULL)),
  CHECK(watermark_asset_id IS NULL OR watermark_asset_id <> id),
  CHECK(access_class <> 'public' OR watermark_asset_id IS NULL)
);
CREATE INDEX ix_asset_sha ON cms_asset(sha256);
CREATE INDEX ix_asset_kind ON cms_asset(kind, created_at);

-- Old keys 301 to the live key. Never an FK target.
CREATE TABLE cms_asset_alias (
  key TEXT PRIMARY KEY COLLATE NOCASE,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Derived bytes. Not content: no page or user table may reference a variant.
CREATE TABLE cms_asset_variant (
  id INTEGER PRIMARY KEY,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE CASCADE,
  label TEXT NOT NULL CHECK(label IN ('thumb','md','lg','og')),
  format TEXT NOT NULL CHECK(format IN ('webp','avif','jpeg','png')),
  width INTEGER NOT NULL,
  height INTEGER NOT NULL,
  bytes INTEGER NOT NULL,
  sha256 TEXT NOT NULL,
  storage_path TEXT NOT NULL,
  CONSTRAINT ux_variant UNIQUE(asset_id, label, format)
);

-- The usage graph. Deletion is refused while a link exists; orphan sweep is an explicit report.
CREATE TABLE cms_asset_link (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  owner_kind TEXT NOT NULL CHECK(owner_kind IN ('page','settings','bundle','datasource')),
  owner_id INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CONSTRAINT ux_link UNIQUE(asset_id, owner_kind, owner_id)
);
CREATE INDEX ix_link_owner ON cms_asset_link(owner_kind, owner_id);

-- Sellable set. A code points at an asset or a bundle, never both.
CREATE TABLE cms_asset_bundle (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(key = lower(key) AND key NOT GLOB '*[^a-z0-9-]*'),
  title TEXT NOT NULL,
  note TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE cms_asset_bundle_item (
  bundle_id INTEGER NOT NULL REFERENCES cms_asset_bundle(id) ON DELETE CASCADE,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE RESTRICT,
  position INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY(bundle_id, asset_id),
  CONSTRAINT ux_bundle_item_pos UNIQUE(bundle_id, position)
);

-- code_lookup is an HMAC for O(1) seek; code_hash is argon2id and is NEVER queried by equality.
CREATE TABLE cms_download_code (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code_lookup TEXT NOT NULL UNIQUE CHECK(length(code_lookup) = 64),
  code_hash TEXT NOT NULL,
  asset_id INTEGER REFERENCES cms_asset(id) ON DELETE RESTRICT,
  bundle_id INTEGER REFERENCES cms_asset_bundle(id) ON DELETE RESTRICT,
  max_uses INTEGER CHECK(max_uses IS NULL OR max_uses BETWEEN 1 AND 100),
  uses INTEGER NOT NULL DEFAULT 0 CHECK(uses >= 0),
  expires_at TEXT,
  issued_to_email TEXT,
  order_ref TEXT,
  revoked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  last_used_at TEXT,
  CHECK((asset_id IS NULL) <> (bundle_id IS NULL))
);
CREATE INDEX ix_code_asset ON cms_download_code(asset_id, created_at);

-- Append-only redemption log. Never updated.
CREATE TABLE cms_download_event (
  id INTEGER PRIMARY KEY,
  code_id INTEGER REFERENCES cms_download_code(id) ON DELETE SET NULL,
  asset_id INTEGER REFERENCES cms_asset(id) ON DELETE SET NULL,
  ip_hash TEXT,
  ua_hash TEXT,
  bytes_sent INTEGER NOT NULL DEFAULT 0 CHECK(bytes_sent >= 0),
  ranged INTEGER NOT NULL DEFAULT 0 CHECK(ranged IN (0,1)),
  outcome TEXT NOT NULL CHECK(outcome IN ('ok','denied_quota','denied_expired','denied_revoked','denied_token','denied_watermark')),
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_ev_code_ts ON cms_download_event(code_id, ts);
CREATE INDEX ix_ev_ts ON cms_download_event(ts);

-- Render cache. Key includes the rendered spec because bytes differ per purchaser.
CREATE TABLE cms_watermark_render (
  id INTEGER PRIMARY KEY,
  asset_id INTEGER NOT NULL REFERENCES cms_asset(id) ON DELETE CASCADE,
  spec_sha TEXT NOT NULL,
  source_sha TEXT NOT NULL,
  bytes INTEGER NOT NULL,
  path TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CONSTRAINT ux_wm UNIQUE(spec_sha, source_sha)
);

-- mode='forward' means the export never emits a dead form.
CREATE TABLE cms_form (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(key = lower(key) AND key NOT GLOB '*[^a-z0-9-]*'),
  title TEXT NOT NULL,
  fields_json TEXT NOT NULL,
  mode TEXT NOT NULL DEFAULT 'store' CHECK(mode IN ('store','forward','disabled')),
  action_url TEXT,
  notify_email TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK(mode <> 'forward' OR action_url IS NOT NULL)
);

CREATE TABLE cms_form_submission (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  form_id INTEGER NOT NULL REFERENCES cms_form(id) ON DELETE CASCADE,
  payload_json TEXT NOT NULL,
  ip_hash TEXT,
  spam_score REAL NOT NULL DEFAULT 0,
  state TEXT NOT NULL DEFAULT 'new' CHECK(state IN ('new','read','spam','forwarded')),
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_sub_form_ts ON cms_form_submission(form_id, ts);

-- kind='function' removed from v1: JS source is a code-execution path and a read-only handle can ATTACH another tenant.
CREATE TABLE cms_datasource (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(key = lower(key) AND key NOT GLOB '*[^a-z0-9-]*'),
  kind TEXT NOT NULL CHECK(kind IN ('view','query')),
  spec_json TEXT NOT NULL CHECK(json_valid(spec_json)),
  is_public INTEGER NOT NULL DEFAULT 0 CHECK(is_public IN (0,1)),
  ttl_s INTEGER NOT NULL DEFAULT 60 CHECK(ttl_s BETWEEN 0 AND 86400),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  published_at TEXT,
  published_by INTEGER
);
CREATE INDEX ix_ds_public ON cms_datasource(is_public);

-- Views are migration-owned. A view not in this registry fails the DDL runner's postcondition.
CREATE TABLE cms_view_registry (
  name TEXT PRIMARY KEY CHECK(name GLOB 'cms_v_*'),
  checksum TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- One row per u_* table. Written in the same transaction as the DDL.
CREATE TABLE cms_table_registry (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  table_name TEXT NOT NULL UNIQUE CHECK(table_name GLOB 'u_*'),
  ddl_version INTEGER NOT NULL DEFAULT 1,
  column_count INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by INTEGER,
  notes TEXT
);

-- Tenant-plane audit. Travels with the export. No single action is written here and to control.db.
CREATE TABLE cms_audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  actor_user_id INTEGER,
  actor_label TEXT NOT NULL,
  action TEXT NOT NULL,
  target_kind TEXT,
  target_id TEXT,
  before_json TEXT,
  after_json TEXT,
  ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX ix_ca_ts ON cms_audit(ts);
CREATE INDEX ix_ca_action ON cms_audit(action, ts);

-- Nobody specified this; every slug rename is a 404 without it.
CREATE TABLE cms_redirect (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  from_path TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK(from_path GLOB '/*'),
  to_path TEXT NOT NULL CHECK(to_path GLOB '/*'),
  status INTEGER NOT NULL DEFAULT 301 CHECK(status IN (301,302,308)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  hits INTEGER NOT NULL DEFAULT 0
);

-- u_* tables are created at runtime by the DDL runner; they are NOT declared here.

